def solve(**kwargs):
    n = kwargs['n']
    matrix = kwargs['matrix']
    m = len(matrix[0]) if n > 0 else 0
    if n == 0:
        return {'job_sequence': []}
    INF = float('inf')
    # dp[mask][j] = list of completion times on m machines for set mask ending with job j
    dp = [[None] * n for _ in range(1 << n)]
    prev = [[-1] * n for _ in range(1 << n)]
    for j in range(n):
        comps = [0] * m
        for t in range(m):
            comps[t] = matrix[j][t]
        dp[1 << j][j] = comps[:]
    for mask in range(1 << n):
        for j in range(n):
            if dp[mask][j] is None:
                continue
            for k in range(n):
                if mask & (1 << k):
                    continue
                prev_comps = dp[mask][j]
                new_comps = [0] * m
                for t in range(m):
                    if t == 0:
                        start = prev_comps[0] + matrix[k][0]
                    else:
                        start = max(prev_comps[t], new_comps[t - 1]) + matrix[k][t]
                    new_comps[t] = start
                new_mask = mask | (1 << k)
                if dp[new_mask][k] is None or new_comps[k] < dp[new_mask][k]:
                    dp[new_mask][k] = new_comps[:]
                    prev[new_mask][k] = j
    full_mask = (1 << n) - 1
    best_ms = INF
    best_j = -1
    for j in range(n):
        if dp[full_mask][j] is not None and dp[full_mask][j][m - 1] < best_ms:
            best_ms = dp[full_mask][j][m - 1]
            best_j = j
    # reconstruct sequence
    seq = []
    mask = full_mask
    cur = best_j
    while cur != -1:
        seq.append(cur)
        prev_j = prev[mask][cur]
        mask = mask & ~(1 << cur)
        cur = prev_j
    seq.reverse()
    return {'job_sequence': [x + 1 for x in seq]}
