        for i in range(1, n):
            C[i][0] = C[i-1][0] + p[i][0]
        for j in range(1, m):
            for i in range(1, n):
                C[i][j] = max(C[i-1][j], C[i][j-1]) + p[i][j]
        return C[n-1][m-1]
    best_seq = jobs[:2]
    ms1 = makespan(best_seq)
    best_seq = jobs[1:3]
    ms2 = makespan(best_seq)
    if ms1 < ms2:
        best_seq = jobs[:2]
    else:
        best_seq = jobs[1:3]
    for k in range(2, n):
        job = jobs[k]
        best_insert = None
        best_ms = float('inf')
        for pos in range(len(best_seq) + 1):
            seq = best_seq[:pos] + [job] + best_seq[pos:]
            ms = makespan(seq)
            if ms < best_ms:
                best_ms = ms
                best_insert = pos
